//! Nono (f0=0) .pth 直読みのパリティ検証 (dev 専用・実ファイル依存)。
//! cargo test -p rcwx-nn --test nono_parity -- --ignored --nocapture
use rcwx_nn::engine::{Backend, Engine};
use rcwx_nn::synth::Synth;

#[test]
#[ignore = "requires nono_test.pth generated by dev tools"]
fn nono_pth_direct_load() {
    let base = std::path::Path::new("C:/Users/donoy/AppData/Local/Temp/rcwx-verify");
    let eng = Engine::new(Backend::Dx12).unwrap();
    let synth = Synth::load_from_pth(&eng, &base.join("nono_test.pth")).unwrap();
    assert!(!synth.cfg.has_f0);
    assert_eq!(synth.cfg.sr, 40000);
    println!(
        "nono cfg: v{} layers={} sr={} spk={}",
        synth.cfg.version, synth.cfg.n_layers, synth.cfg.sr, synth.cfg.n_speakers
    );
    let t: u32 = 49;
    let feats_raw = std::fs::read(base.join("nono_feats.bin")).unwrap();
    let feats: Vec<f32> = feats_raw
        .chunks_exact(4)
        .map(|c| f32::from_le_bytes([c[0], c[1], c[2], c[3]]))
        .collect();
    assert_eq!(feats.len(), 49 * 768);
    let ft = eng.tensor_from_f32(&feats, vec![]);
    let z = synth.encode_raw(&eng, &ft, &[0u32; 49], t);
    let zc = synth.cfg.sr as usize / 100;
    let zero_har = vec![0f32; (t as usize) * zc];
    let audio = synth.decode_window(&eng, &z, &zero_har, 0, t);
    let out = eng.readback_f32(&audio);
    // Python 参照と corr
    let ref_raw = std::fs::read(base.join("nono_ref.f32")).unwrap();
    let expect: Vec<f32> = ref_raw
        .chunks_exact(4)
        .map(|c| f32::from_le_bytes([c[0], c[1], c[2], c[3]]))
        .collect();
    let n = expect.len().min(out.len());
    let corr = rcwx_nn::cosine(&out[..n], &expect[..n]);
    println!("nono audio len {} vs ref {}, corr = {corr:.6}", out.len(), expect.len());
    assert!(corr > 0.999, "nono corr too low: {corr}");
}
